CREATE TABLE IF NOT EXISTS economic_cashflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES economic_entities(id) ON DELETE CASCADE, activity_id uuid REFERENCES economic_activities(id) ON DELETE SET NULL, direction text NOT NULL, amount numeric(20,2) NOT NULL, currency text NOT NULL DEFAULT 'NGN', occurred_on date NOT NULL, category text, evidence_ref text, source_type text, verification_status text NOT NULL DEFAULT 'reported', created_at timestamptz NOT NULL DEFAULT now());